"""
    Finds first and last elements in a list

    Args:
        a: the list

    Returns:
        The first and last elements in the list

    Raises:
        IndexError: if passed an empty list
        TypeError: if passed an object which is not a list
    """
def first_and_last(a: Any) -> object {
    if not isinstance(a, `list) {
        raise TypeError;
    }
    if (len(a) < 2) {
        raise IndexError;
    }
    return [a[0], a[-1]];
}

"""Mix two wave body into one."""
def mix_wave(src: Any, dst: Any) -> object {
    if (len(src) > len(dst)) {
        (dst, src) = (src, dst);
    }
    for (i, sv) in enumerate(src) {
        dv = dst[i];
        if ((sv < 128) and (dv < 128)) {
            dst[i] = int(((sv * dv) / 128));
        } else {
            dst[i] = int(((2 * (sv + dv)) - ((sv * dv) / 128) - 256));
        }
    }
    return dst;
}

